// ================= IMPLEMENTATION =================
// ===== begin src/cpp/src/formats/face_cells_common.hpp =====
/**
 * @file formats/face_cells_common.hpp
 * @brief Volume cells from their faces: the kernel shared by the readers of
 *        face-based formats (OpenFOAM `polyMesh`, ANSYS Fluent `.msh`).
 *
 * A cell is given as its faces, each a list of point ids wound so that its
 * right-hand normal points out of the cell. Tetrahedra, pyramids, wedges and
 * hexahedra come back in meshio++'s (VTK) node order with a positive volume --
 * the orientation is checked geometrically, so a flipped input face does not
 * invert the cell; anything else is reported as a polyhedron and the caller
 * keeps its outward faces. `polygon_from_edges` does the 2-D counterpart.
 *
 * A **format-private** header (the `gid_common.hpp` precedent): it sits beside
 * the `.cpp` files, is never installed, and lives in a *named* namespace
 * because the amalgamation concatenates every source into one translation
 * unit. Twin of `src/python/meshioplusplus/_face_cells.py`.
 */

#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>

namespace meshioplusplus {
namespace face_cells {

using Face = std::vector<std::int64_t>;
using P3 = std::vector<std::array<double, 3>>;

inline double triple(const std::array<double, 3>& rA, const std::array<double, 3>& rB,
                     const std::array<double, 3>& rC) {
    // a . (b x c)
    double cx = rB[1] * rC[2] - rB[2] * rC[1];
    double cy = rB[2] * rC[0] - rB[0] * rC[2];
    double cz = rB[0] * rC[1] - rB[1] * rC[0];
    return rA[0] * cx + rA[1] * cy + rA[2] * cz;
}

inline std::array<double, 3> sub(const std::array<double, 3>& rA, const std::array<double, 3>& rB) {
    return {rA[0] - rB[0], rA[1] - rB[1], rA[2] - rB[2]};
}

inline std::size_t unique_node_count(const std::vector<Face>& rFaces) {
    std::unordered_set<std::int64_t> s;
    for (const auto& f : rFaces)
        for (std::int64_t v : f)
            s.insert(v);
    return s.size();
}

inline std::unordered_map<std::int64_t, std::unordered_set<std::int64_t>> node_adjacency(
    const std::vector<Face>& rFaces) {
    std::unordered_map<std::int64_t, std::unordered_set<std::int64_t>> adj;
    for (const auto& f : rFaces) {
        std::size_t m = f.size();
        for (std::size_t i = 0; i < m; ++i) {
            std::int64_t a = f[i], b = f[(i + 1) % m];
            adj[a].insert(b);
            adj[b].insert(a);
        }
    }
    return adj;
}

// Returns the ordered top ring, or empty if ambiguous.
inline std::vector<std::int64_t> match_top(const Face& rBottom,
                                           const std::vector<Face>& rOriented) {
    auto adj = node_adjacency(rOriented);
    std::unordered_set<std::int64_t> base(rBottom.begin(), rBottom.end());
    std::vector<std::int64_t> top;
    for (std::int64_t b : rBottom) {
        std::vector<std::int64_t> cand;
        for (std::int64_t x : adj[b])
            if (!base.count(x))
                cand.push_back(x);
        if (cand.size() != 1)
            return {};
        top.push_back(cand[0]);
    }
    return top;
}

inline Face build_tetra(const std::vector<Face>& rOriented, const P3& rP) {
    const Face& base = rOriented[0];
    std::unordered_set<std::int64_t> all;
    for (const auto& f : rOriented)
        for (std::int64_t v : f)
            all.insert(v);
    for (std::int64_t v : base)
        all.erase(v);
    std::int64_t apex = *all.begin();
    Face n = {base[0], base[1], base[2], apex};
    if (triple(sub(rP[n[1]], rP[n[0]]), sub(rP[n[2]], rP[n[0]]), sub(rP[n[3]], rP[n[0]])) < 0)
        n = {base[0], base[2], base[1], apex};
    return n;
}

inline Face build_pyramid(const std::vector<Face>& rOriented, const P3& rP) {
    Face quad;
    for (const auto& f : rOriented)
        if (f.size() == 4) {
            quad = f;
            break;
        }
    std::unordered_set<std::int64_t> all;
    for (const auto& f : rOriented)
        for (std::int64_t v : f)
            all.insert(v);
    for (std::int64_t v : quad)
        all.erase(v);
    std::int64_t apex = *all.begin();
    Face n = {quad[0], quad[1], quad[2], quad[3], apex};
    if (triple(sub(rP[n[1]], rP[n[0]]), sub(rP[n[3]], rP[n[0]]), sub(rP[n[4]], rP[n[0]])) < 0)
        n = {quad[0], quad[3], quad[2], quad[1], apex};
    return n;
}

inline Face build_wedge(const std::vector<Face>& rOriented, const P3& rP) {
    Face bottom;
    for (const auto& f : rOriented)
        if (f.size() == 3) {
            bottom = f;
            break;
        }
    std::vector<std::int64_t> top = match_top(bottom, rOriented);
    if (top.empty())
        return {};
    Face n = {bottom[0], bottom[1], bottom[2], top[0], top[1], top[2]};
    if (triple(sub(rP[n[1]], rP[n[0]]), sub(rP[n[2]], rP[n[0]]), sub(rP[n[3]], rP[n[0]])) < 0)
        n = {bottom[0], bottom[2], bottom[1], top[0], top[2], top[1]};
    return n;
}

inline Face build_hexahedron(const std::vector<Face>& rOriented, const P3& rP) {
    Face bottom;
    for (const auto& f : rOriented)
        if (f.size() == 4) {
            bottom = f;
            break;
        }
    std::vector<std::int64_t> top = match_top(bottom, rOriented);
    if (top.empty())
        return {};
    Face n = {bottom[0], bottom[1], bottom[2], bottom[3], top[0], top[1], top[2], top[3]};
    if (triple(sub(rP[n[1]], rP[n[0]]), sub(rP[n[3]], rP[n[0]]), sub(rP[n[4]], rP[n[0]])) < 0)
        n = {bottom[0], bottom[3], bottom[2], bottom[1], top[0], top[3], top[2], top[1]};
    return n;
}

// Classify a cell. Returns {meshio type, connectivity}. For "polyhedron" the
// connectivity is empty (the caller keeps the oriented faces).
inline std::pair<std::string, Face> reconstruct_cell(const std::vector<Face>& rOriented,
                                                     const P3& rP) {
    std::size_t nf = rOriented.size();
    std::size_t np = unique_node_count(rOriented);
    if (nf == 4 && np == 4)
        return {"tetra", build_tetra(rOriented, rP)};
    if (nf == 5 && np == 5)
        return {"pyramid", build_pyramid(rOriented, rP)};
    if (nf == 5 && np == 6)
        return {"wedge", build_wedge(rOriented, rP)};
    if (nf == 6 && np == 8)
        return {"hexahedron", build_hexahedron(rOriented, rP)};
    return {"polyhedron", {}};
}

// Chain a 2-D cell's boundary edges into one ring of point ids, counter-
// clockwise in the xy plane. Empty when the edges do not close a single loop.
inline Face polygon_from_edges(const std::vector<std::array<std::int64_t, 2>>& rEdges,
                               const P3& rP) {
    if (rEdges.size() < 3)
        return {};
    std::unordered_map<std::int64_t, std::vector<std::int64_t>> next;
    for (const auto& e : rEdges) {
        next[e[0]].push_back(e[1]);
        next[e[1]].push_back(e[0]);
    }
    for (const auto& [node, nbrs] : next)
        if (nbrs.size() != 2)
            return {};
    const std::int64_t start = rEdges[0][0];
    Face ring = {start, rEdges[0][1]};
    while (ring.size() < next.size()) {
        const auto& nbrs = next[ring.back()];
        const std::int64_t c = nbrs[0] != ring[ring.size() - 2] ? nbrs[0] : nbrs[1];
        if (c == start)
            return {};
        ring.push_back(c);
    }
    const auto& last = next[ring.back()];
    if (ring.size() != rEdges.size() || (last[0] != start && last[1] != start))
        return {};
    double area = 0.0;
    for (std::size_t i = 0; i < ring.size(); ++i) {
        const auto& a = rP[static_cast<std::size_t>(ring[i])];
        const auto& b = rP[static_cast<std::size_t>(ring[(i + 1) % ring.size()])];
        area += a[0] * b[1] - b[0] * a[1];
    }
    if (area < 0)
        std::reverse(ring.begin() + 1, ring.end());
    return ring;
}

}  // namespace face_cells
}  // namespace meshioplusplus
// ===== end src/cpp/src/formats/face_cells_common.hpp =====
// ===== begin src/cpp/src/formats/gid_common.hpp =====
/**
 * @file formats/gid_common.hpp
 * @brief Path/flavour helpers shared by the GiD writer and reader.
 *
 * A **format-private** header (the `formats/xdmf_doc.hpp` precedent, included
 * by both `xdmf.cpp` and `xdmf_time_series.cpp`): it lives beside the `.cpp`
 * files rather than under `src/cpp/include/`, because nothing outside this
 * format needs it and no installed header may name it. The amalgamator
 * resolves a quoted include against the including file's own directory first,
 * so it is inlined exactly once with no generator change.
 *
 * These three helpers used to sit in `gid.cpp`'s anonymous namespace **inside**
 * its `#ifdef MESHIOPLUSPLUS_HAS_GIDPOST` guard. They moved here for two
 * reasons, and both matter:
 *
 *  1. The **reader needs them but must not be behind that guard.** gidpost is
 *     a write-only library; reading a GiD file is ordinary text/record parsing
 *     whose real dependencies are per-flavour (ASCII: none, binary: zlib,
 *     HDF5: HDF5), not "was gidpost compiled in". Leaving them behind the
 *     guard would have forced the reader behind it too, and a zlib-less build
 *     (the statically-linked release CLI binaries, the Windows wheels) would
 *     then carry no GiD reader for no reason at all.
 *  2. They are in a **named** namespace, not an anonymous one, because the
 *     amalgamation concatenates every `src/cpp/src/**.cpp` into a single
 *     translation unit -- two files each carrying an anonymous-namespace
 *     `gid_has_suffix` would be a redefinition there even though they compile
 *     fine separately.
 */

// System includes
#include <array>
#include <cstddef>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {
namespace gid_detail {

/// True when @p rS ends with @p rSuffix.
inline bool gid_has_suffix(const std::string& rS, const std::string& rSuffix) {
    return rS.size() >= rSuffix.size() &&
           rS.compare(rS.size() - rSuffix.size(), rSuffix.size(), rSuffix) == 0;
}

/**
 * @brief Resolves `GidMode::Auto` against a path's extension.
 *
 * `.post.bin` -> Binary, `.post.h5` -> Hdf5, anything else (including
 * `.post.msh`/`.post.res`) -> Ascii. A non-`Auto` mode passes through.
 *
 * @note On the READ side this is only the first guess: `read_gid` additionally
 * sniffs the leading bytes, because a `.post.msh` may legitimately be gzipped
 * (gidpost's `GiD_PostAsciiZipped` writes the same ASCII text through
 * `gzprintf`), and the extension alone cannot say so.
 */
inline GidMode gid_resolve_mode(const std::string& rPath, GidMode mode) {
    if (mode != GidMode::Auto)
        return mode;
    if (gid_has_suffix(rPath, ".post.bin"))
        return GidMode::Binary;
    if (gid_has_suffix(rPath, ".post.h5"))
        return GidMode::Hdf5;
    return GidMode::Ascii;
}

/**
 * @brief `"<stem>.post.msh"` <-> `"<stem>.post.res"`.
 *
 * An arbitrary path is treated as the stem itself (the
 * `ensight_case_geo_paths` precedent, generalized to a third case since gid's
 * two known suffixes share the same length).
 *
 * @return `{mesh path, result path}`.
 */
inline std::pair<std::string, std::string> gid_ascii_paths(const std::string& rPath) {
    if (gid_has_suffix(rPath, ".post.msh"))
        return {rPath, rPath.substr(0, rPath.size() - 3) + "res"};
    if (gid_has_suffix(rPath, ".post.res"))
        return {rPath.substr(0, rPath.size() - 3) + "msh", rPath};
    return {rPath + ".post.msh", rPath + ".post.res"};
}

/**
 * @brief The one `{GidResultType, GiD spelling, legal component counts}`
 * table, shared by the writer and the reader.
 *
 * Counts are gidpost's own `_ResultTypeInfo` (`gidpostInt.c`); spellings are
 * what `GetResultTypeName` emits and what a `.post.res` `Result` header
 * therefore carries. A single table because the reader validates counts it
 * parsed and the writer validates counts it is about to emit -- two
 * transcriptions of an irregular nine-row table would drift, and a wrong row
 * produces a plausible-looking file rather than an error.
 *
 * A zero terminates the count list (gidpost's own convention).
 */
struct GidResultTypeEntry {
    GidResultType mType;
    const char* mName;
    std::array<std::size_t, 3> mDims;  // zero-terminated
};

inline const std::vector<GidResultTypeEntry>& gid_result_type_table() {
    static const std::vector<GidResultTypeEntry> table = {
        {GidResultType::Scalar, "Scalar", {1, 0, 0}},
        {GidResultType::Vector, "Vector", {2, 3, 4}},
        {GidResultType::Matrix, "Matrix", {3, 6, 0}},
        {GidResultType::PlainDeformationMatrix, "PlainDeformationMatrix", {4, 0, 0}},
        {GidResultType::MainMatrix, "MainMatrix", {12, 0, 0}},
        {GidResultType::LocalAxes, "LocalAxes", {3, 0, 0}},
        {GidResultType::ComplexScalar, "ComplexScalar", {2, 0, 0}},
        {GidResultType::ComplexVector, "ComplexVector", {4, 6, 0}},
        {GidResultType::ComplexMatrix, "ComplexMatrix", {6, 12, 0}},
    };
    return table;
}

/// The entry for @p type, or nullptr when @p type is out of range (which a
/// caller-supplied `field_data` value can be).
inline const GidResultTypeEntry* gid_find_result_type(GidResultType type) {
    for (const GidResultTypeEntry& e : gid_result_type_table())
        if (e.mType == type)
            return &e;
    return nullptr;
}

/// Human-readable legal counts for @p type, for an error message.
inline std::string gid_legal_dims_text(const GidResultTypeEntry& rEntry) {
    std::string out;
    for (std::size_t d : rEntry.mDims) {
        if (d == 0)
            break;
        if (!out.empty())
            out += ", ";
        out += std::to_string(d);
    }
    return out;
}

/**
 * @brief The type the writer picks for a @p k -component array with no
 * declaration, or nullptr when it would split the array into k scalars.
 *
 * Shared so the reader can decide whether a declaration carries information:
 * it records one only when the file's declared type differs from what this
 * would have inferred, which is what keeps an ordinary scalar/3-vector round
 * trip free of `gid:result_type:*` noise (the all-zero-material-column rule).
 */
inline const GidResultTypeEntry* gid_inferred_result_type(std::size_t k) {
    if (k == 1)
        return gid_find_result_type(GidResultType::Scalar);
    if (k == 2 || k == 3)
        return gid_find_result_type(GidResultType::Vector);
    return nullptr;
}

/**
 * @brief Node-slot permutations for the three quadratic cell types whose GiD
 * ordering was, until now, "not independently verified" -- `hexahedron27`,
 * `wedge15`, `pyramid13`.
 *
 * Shared between the writer and the reader for the same reason the result
 * type table above is: a permutation transcribed twice risks two silently
 * different tables, and a wrong entry here does not fail loudly -- it writes
 * or reads a plausible file with quietly transposed quadratic nodes.
 *
 * ## Derivation
 *
 * Every entry meshio++ already supported was cross-checked against Kratos
 * Multiphysics's production GiD writer; these three were refused because no
 * such cross-check existed. Read from Kratos's own geometry classes
 * (`kratos/geometries/hexahedra_3d_27.h`, `prism_3d_15.h`, `pyramid_3d_13.h`)
 * and independently confirmed against Kratos's Kratos-to-VTK conversion
 * utility (`kratos/input_output/vtk_output.cpp`, mirrored in
 * `ensight_output.cpp`) -- an Element-agnostic source, unlike the
 * Hexahedra3D20 reorder in `gid_mesh_container.h`, which the research
 * confirming this table found lives only in that file's *Conditions*-writing
 * path (elements are written with no reorder at all). That does not change
 * `hexahedron20`'s own identity mapping below -- `vtk_output.cpp`'s
 * conversion, which every Hexahedra3D20 element or condition goes through for
 * VTK/EnSight output, independently reproduces the identical swap -- but it
 * is the more precise citation and the one these three lean on, since two of
 * them (`hexahedron27`, `wedge15`) have no GiD-specific Kratos precedent at
 * all beyond "no reorder is applied", and the third (`pyramid13`) has no
 * Kratos GiD precedent whatsoever -- Kratos never registers a GiD mesh
 * container for any pyramid, of any order, so its ordering rests on Kratos's
 * internal geometry convention alone (confirmed to already equal VTK's own
 * convention by `vtk_output.cpp` explicitly skipping it: `Pyramid3D13` falls
 * through that function's `else` branch, needing no conversion).
 *
 * `hexahedron27`: meshio++'s own table (`cell_subdivision.cpp`) orders edges
 * 8-11 bottom ring, 12-15 TOP ring, 16-19 verticals; Kratos's internal order
 * is 8-11 bottom ring, 12-15 VERTICALS, 16-19 top ring -- the reverse split.
 * Face centres 20-25 also disagree: meshio++ orders them x-min/x-max/y-min/
 * y-max/bottom/top, Kratos orders them bottom/y-min/x-max/y-max/x-min/top.
 * Body centre 26 agrees. The permutation below is `dst[c] = src[p[c]]` (the
 * `med_node_perm()`/`flatten_f`/`unflatten_f` convention already used
 * elsewhere in this repo, reused rather than reinvented) mapping a
 * GiD/Kratos slot to the meshio++ index holding the same edge/face/body; it
 * is self-inverse (an involution), like every other permutation this
 * convention has produced so far, and matches `vtk_output.cpp`'s own
 * Kratos-index array verbatim.
 *
 * `wedge15`: meshio++ orders edges 6-8 bottom triangle, 9-11 TOP triangle,
 * 12-14 verticals; Kratos orders 6-8 bottom triangle, 9-11 VERTICALS, 12-14
 * top triangle -- the same reverse-split pattern, and again self-inverse.
 *
 * `pyramid13`: identical in both conventions (base-ring edges 5-8, apex
 * edges 9-12) -- no permutation, `mPerm == nullptr`.
 */
struct GidCellPermEntry {
    const char* mMeshioName;
    std::size_t mNumNodes;
    const int* mPerm;  // nullptr = identity
};

/// `dst[c] = src[p[c]]`, self-inverse. See `hexahedron27`'s derivation above;
/// independently confirmed against Kratos's `vtk_output.cpp` array verbatim.
/// Indexed and grouped deliberately, not a flat literal, so a slipped digit
/// here is easy to catch by eye against the derivation comment above:
///   corners 0-7, bottom-ring edges 8-11: identity
///   top-ring edges 12-15 <- meshio++'s verticals 16-19
///   verticals 16-19      <- meshio++'s top-ring edges 12-15
///   face centres: 20<-24(bottom), 21<-22(y-min), 22<-21(x-max),
///                 23<-23(y-max, fixed), 24<-20(x-min), 25<-25(top, fixed)
///   body centre 26: fixed
inline constexpr int kGidHexahedron27Perm[27] = {
    0,  1,  2,  3,  4,  5,  6, 7,  // corners
    8,  9,  10, 11,                // bottom-ring edges
    16, 17, 18, 19,                // slot 12-15 (top ring)   <- verticals
    12, 13, 14, 15,                // slot 16-19 (verticals)  <- top ring
    24, 22, 21, 23, 20, 25,        // face centres 20-25
    26,                            // body centre
};

/// `dst[c] = src[p[c]]`, self-inverse. See `wedge15`'s derivation above:
///   corners 0-5, bottom-triangle edges 6-8: identity
///   top-triangle edges 9-11 <- meshio++'s verticals 12-14
///   verticals 12-14         <- meshio++'s top-triangle edges 9-11
inline constexpr int kGidWedge15Perm[15] = {
    0,  1,  2,  3, 4, 5,  // corners
    6,  7,  8,            // bottom-triangle edges
    12, 13, 14,           // slot 9-11 (top triangle) <- verticals
    9,  10, 11,           // slot 12-14 (verticals)   <- top triangle
};

inline const std::vector<GidCellPermEntry>& gid_cell_perm_table() {
    static const std::vector<GidCellPermEntry> table = {
        {"hexahedron27", 27, kGidHexahedron27Perm},
        {"wedge15", 15, kGidWedge15Perm},
        {"pyramid13", 13, nullptr},
    };
    return table;
}

/// The permutation for @p rMeshioName / @p nnode, or nullptr for identity
/// (either because the type needs none, like `pyramid13`, or because it is
/// not in this table at all -- every OTHER GiD-supported type is identity).
inline const int* gid_cell_perm(const std::string& rMeshioName, std::size_t nnode) {
    for (const GidCellPermEntry& e : gid_cell_perm_table())
        if (e.mNumNodes == nnode && rMeshioName == e.mMeshioName)
            return e.mPerm;
    return nullptr;
}

/**
 * @brief Which Gauss-point counts GiD can place itself (`Natural Coordinates:
 * Internal`), per meshio++ cell type, and how many natural-coordinate
 * components a `Given` point needs for that type.
 *
 * Transcribed from CIMNE's GiD Customization Manual. Shared between the writer
 * (which must refuse an Internal-impossible count that supplies no
 * coordinates) and the reader (which must know a Given set's coordinate width
 * to round-trip it) -- two transcriptions of an irregular six-row table would
 * drift silently, and the failure mode is a file GiD rejects rather than an
 * error meshio++ raises.
 *
 * `mCoordDim == 0` marks the line family, which is special twice over: it
 * accepts **any** count Internally (equally spaced), and GiD forbids `Given`
 * for it outright. `mAnyCount` therefore implies "never needs coordinates".
 *
 * A zero terminates the count list, the same convention
 * `GidResultTypeEntry::mDims` uses.
 */
struct GidGaussCountEntry {
    const char* mMeshioName;
    std::array<std::size_t, 3> mInternalCounts;  // zero-terminated
    bool mAnyCount;                              // line family: any G, Given forbidden
    std::size_t mCoordDim;                       // 0 = Given not permitted
};

inline const std::vector<GidGaussCountEntry>& gid_gauss_count_table() {
    static const std::vector<GidGaussCountEntry> table = {
        // 2-D families: natural coordinates are (a, b).
        {"triangle", {1, 3, 6}, false, 2},
        {"quad", {1, 4, 9}, false, 2},
        // 3-D families: natural coordinates are (a, b, c).
        {"tetra", {1, 4, 10}, false, 3},
        {"hexahedron", {1, 8, 27}, false, 3},
        {"wedge", {1, 6, 0}, false, 3},
        {"pyramid", {1, 5, 0}, false, 3},
        // Line elements: any count, equally spaced; Given is forbidden.
        {"line", {0, 0, 0}, true, 0},
    };
    return table;
}

/**
 * @brief The Gauss-count entry governing @p rMeshioName, or nullptr.
 *
 * Higher-order variants share their base family's Gauss-point rules (a
 * `tetra10` is still a tetrahedron as far as quadrature goes), so the lookup
 * matches on the longest table name that prefixes the type -- `hexahedron27`
 * -> `hexahedron`, `triangle6` -> `triangle`, `line3` -> `line`. Matching on
 * the longest entry matters: `quad` must not swallow a name that a longer
 * entry would claim, and this keeps the table one row per family rather than
 * one per concrete type.
 */
inline const GidGaussCountEntry* gid_find_gauss_counts(const std::string& rMeshioName) {
    const GidGaussCountEntry* best = nullptr;
    for (const GidGaussCountEntry& e : gid_gauss_count_table()) {
        const std::string name = e.mMeshioName;
        if (rMeshioName.rfind(name, 0) != 0)
            continue;
        if (best == nullptr || name.size() > std::string(best->mMeshioName).size())
            best = &e;
    }
    return best;
}

/// Whether GiD can place @p g points itself for @p rMeshioName (so the set may
/// be written `Natural Coordinates: Internal`). An unknown type is permissive:
/// only counts we positively know to be impossible are refused.
inline bool gid_gauss_count_is_internal(const std::string& rMeshioName, std::size_t g) {
    const GidGaussCountEntry* e = gid_find_gauss_counts(rMeshioName);
    if (e == nullptr)
        return true;
    if (e->mAnyCount)
        return g >= 1;
    for (std::size_t c : e->mInternalCounts) {
        if (c == 0)
            break;
        if (c == g)
            return true;
    }
    return false;
}

/// Human-readable Internal-legal counts for @p rMeshioName, for an error
/// message ("any count" for the line family).
inline std::string gid_internal_counts_text(const GidGaussCountEntry& rEntry) {
    if (rEntry.mAnyCount)
        return "any count";
    std::string out;
    for (std::size_t c : rEntry.mInternalCounts) {
        if (c == 0)
            break;
        if (!out.empty())
            out += ", ";
        out += std::to_string(c);
    }
    return out;
}

/// The `field_data` key carrying a `(cell type, G)` set's natural coordinates.
inline std::string gid_gauss_coords_key(const std::string& rMeshioName, std::size_t g) {
    return std::string(kGidGaussCoordsPrefix) + rMeshioName + ":" + std::to_string(g);
}

}  // namespace gid_detail
}  // namespace meshioplusplus
// ===== end src/cpp/src/formats/gid_common.hpp =====
// ===== begin src/cpp/src/formats/lagrange_common.hpp =====
/**
 * @file formats/lagrange_common.hpp
 * @brief Arbitrary-order Lagrange cells: the `VTK_LAGRANGE_*` node layout and
 *        nodal interpolation between point sets of one polynomial space.
 *
 * - `vtk_lattice` lists the nodes of a VTK Lagrange cell of order `p` as
 *   integer lattice coordinates (`x = i/p` ...) on the reference cell whose
 *   corners are meshio++'s (and MFEM's): the unit segment, the triangle
 *   (0,0) (1,0) (0,1), the unit square, the tetrahedron at the origin and the
 *   unit axes, the unit cube, and the prism of that triangle over [0, 1]. The
 *   order follows VTK: corners, edges, faces, interior (the hexahedron's
 *   vertical edges in VTK 9.1's order). Ported from MFEM's `mesh/vtk.cpp`
 *   (BSD-3-Clause, Lawrence Livermore National Security), which writes the
 *   files ParaView reads.
 * - `interpolation_matrix` maps values at one set of nodes of the cell's
 *   polynomial space (P_p on simplices, Q_p on the square and cube, P_p x P_p
 *   on the prism) to values at other points, through an orthogonal basis
 *   (Legendre products, Dubiner's collapsed bases) so the Vandermonde solve is
 *   well conditioned.
 * - `lattice_weights` names a lattice node by the corners it is a combination
 *   of, with integer weights on a common denominator `p^3`, so the same node
 *   of two cells sharing an edge or face gets the same key.
 *
 * A **format-private** header, beside the `.cpp` files that use it (MFEM
 * today), in a named namespace for the amalgamation. Twin of
 * `src/python/meshioplusplus/_lagrange.py`.
 */

#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <utility>
#include <vector>

namespace meshioplusplus {
namespace lagrange {

enum class Shape { Line, Triangle, Quad, Tetra, Hexahedron, Wedge };

inline int shape_dim(Shape S) {
    switch (S) {
        case Shape::Line:
            return 1;
        case Shape::Triangle:
        case Shape::Quad:
            return 2;
        default:
            return 3;
    }
}

/// Number of nodes of an order-`P` cell.
inline std::size_t num_nodes(Shape S, int P) {
    const std::size_t p = static_cast<std::size_t>(P);
    switch (S) {
        case Shape::Line:
            return p + 1;
        case Shape::Triangle:
            return (p + 1) * (p + 2) / 2;
        case Shape::Quad:
            return (p + 1) * (p + 1);
        case Shape::Tetra:
            return (p + 1) * (p + 2) * (p + 3) / 6;
        case Shape::Hexahedron:
            return (p + 1) * (p + 1) * (p + 1);
        case Shape::Wedge:
            return (p + 1) * (p + 1) * (p + 2) / 2;
    }
    return 0;
}

/// The Gauss-Lobatto points of order `P` on [0, 1], ascending.
inline std::vector<double> gll_points(int P) {
    std::vector<double> x(static_cast<std::size_t>(P) + 1);
    x.front() = 0.0;
    x.back() = 1.0;
    // Interior points: the roots of P'_P on [-1, 1], by Newton from the
    // Chebyshev-Gauss-Lobatto guesses; computed for the lower half and
    // mirrored, so the set is exactly symmetric.
    for (int k = 1; 2 * k <= P; ++k) {
        long double t = -std::cos(3.14159265358979323846264338327950288L * k / P);
        for (int it = 0; it < 100; ++it) {
            // Legendre P_P(t), P'_P(t) by recurrence.
            long double p0 = 1.0L, p1 = t;
            for (int n = 1; n < P; ++n) {
                const long double p2 = ((2 * n + 1) * t * p1 - n * p0) / (n + 1);
                p0 = p1;
                p1 = p2;
            }
            const long double d1 = P * (t * p1 - p0) / (t * t - 1.0L);
            const long double d2 = (2.0L * t * d1 - P * (P + 1) * p1) / (1.0L - t * t);
            const long double step = d1 / d2;
            t -= step;
            if (std::fabs(static_cast<double>(step)) < 1e-19)
                break;
        }
        const double v = static_cast<double>((1.0L + t) / 2.0L);
        x[static_cast<std::size_t>(k)] = v;
        x[static_cast<std::size_t>(P - k)] = 1.0 - v;
    }
    if (P % 2 == 0 && P > 0)
        x[static_cast<std::size_t>(P / 2)] = 0.5;
    return x;
}

/// Equispaced points `i/P` on [0, 1].
inline std::vector<double> uniform_points(int P) {
    std::vector<double> x(static_cast<std::size_t>(P) + 1);
    for (int i = 0; i <= P; ++i)
        x[static_cast<std::size_t>(i)] = static_cast<double>(i) / P;
    return x;
}

// --- VTK node order (after MFEM's mesh/vtk.cpp) ---------------------------------------

inline int vtk_triangle_index(int* pB, int Ref) {
    int max = Ref, min = 0;
    const int bmin = std::min(std::min(pB[0], pB[1]), pB[2]);
    int idx = 0;
    while (bmin > min) {
        idx += 3 * Ref;
        max -= 2;
        ++min;
        Ref -= 3;
    }
    for (int d = 0; d < 3; ++d) {
        if (pB[(d + 2) % 3] == max)
            return idx;
        ++idx;
    }
    for (int d = 0; d < 3; ++d) {
        if (pB[(d + 1) % 3] == min)
            return idx + pB[d] - (min + 1);
        idx += max - (min + 1);
    }
    return idx;
}

inline int vtk_tetra_index(int* pB, int Ref) {
    int idx = 0, max = Ref, min = 0;
    const int bmin = std::min(std::min(std::min(pB[0], pB[1]), pB[2]), pB[3]);
    while (bmin > min) {
        idx += 2 * (Ref * Ref + 1);
        max -= 3;
        ++min;
        Ref -= 4;
    }
    static const int kVertexMax[4] = {3, 0, 1, 2};
    static const int kEdgeMin[6][2] = {{1, 2}, {2, 3}, {0, 2}, {0, 1}, {1, 3}, {0, 3}};
    static const int kEdgeCount[6] = {0, 1, 3, 2, 2, 2};
    static const int kFaceMin[4] = {1, 3, 0, 2};
    static const int kFaceB[4][3] = {{0, 2, 3}, {2, 0, 1}, {2, 1, 3}, {1, 0, 3}};
    for (int v = 0; v < 4; ++v) {
        if (pB[kVertexMax[v]] == max)
            return idx;
        ++idx;
    }
    for (int e = 0; e < 6; ++e) {
        if (pB[kEdgeMin[e][0]] == min && pB[kEdgeMin[e][1]] == min)
            return idx + pB[kEdgeCount[e]] - (min + 1);
        idx += max - (min + 1);
    }
    for (int f = 0; f < 4; ++f) {
        if (pB[kFaceMin[f]] == min) {
            int projected[3];
            for (int i = 0; i < 3; ++i)
                projected[i] = pB[kFaceB[f][i]] - min;
            return idx + vtk_triangle_index(projected, Ref) - 3 * Ref;
        }
        idx += (Ref + 1) * (Ref + 2) / 2 - 3 * Ref;
    }
    return idx;
}

inline int vtk_triangle_offset(int Ref, int I, int J) {
    return I + Ref * (J - 1) - (J * (J + 1)) / 2;
}

inline int vtk_wedge_index(int I, int J, int K, int Ref) {
    const int om1 = Ref - 1;
    const int ibdr = I == 0, jbdr = J == 0, ijbdr = I + J == Ref, kbdr = K == 0 || K == Ref;
    const int nbdr = ibdr + jbdr + ijbdr + kbdr;
    if (nbdr == 3)
        return (ibdr && jbdr ? 0 : (jbdr && ijbdr ? 1 : 2)) + (K ? 3 : 0);
    int offset = 6;
    if (nbdr == 2) {
        if (!kbdr) {
            offset += om1 * 6;
            return offset + (K - 1) + ((ibdr && jbdr) ? 0 : (jbdr && ijbdr ? 1 : 2)) * om1;
        }
        offset += K == Ref ? 3 * om1 : 0;
        if (jbdr)
            return offset + I - 1;
        offset += om1;
        if (ijbdr)
            return offset + J - 1;
        offset += om1;
        return offset + (Ref - J - 1);
    }
    offset += 9 * om1;
    const int ntf = (om1 - 1) * om1 / 2;
    const int nqf = om1 * om1;
    if (nbdr == 1) {
        if (kbdr) {
            if (K > 0)
                offset += ntf;
            return offset + vtk_triangle_offset(Ref, I, J);
        }
        offset += 2 * ntf;
        if (jbdr)
            return offset + (I - 1) + om1 * (K - 1);
        offset += nqf;
        if (ijbdr)
            return offset + (J - 1) + om1 * (K - 1);
        offset += nqf;
        return offset + (Ref - J - 1) + om1 * (K - 1);
    }
    offset += 2 * ntf + 3 * nqf;
    return offset + vtk_triangle_offset(Ref, I, J) + ntf * (K - 1);
}

inline int vtk_tensor_index(int Idx, int Ref, int Dim) {
    const int n = Ref + 1;
    if (Dim == 1) {
        if (Idx == 0 || Idx == Ref)
            return Idx ? 1 : 0;
        return Idx + 1;
    }
    if (Dim == 2) {
        const int i = Idx % n, j = Idx / n;
        const bool ibdr = i == 0 || i == Ref, jbdr = j == 0 || j == Ref;
        if (ibdr && jbdr)
            return i ? (j ? 2 : 1) : (j ? 3 : 0);
        int offset = 4;
        if (jbdr)
            return (i - 1) + (j ? Ref - 1 + Ref - 1 : 0) + offset;
        if (ibdr)
            return (j - 1) + (i ? Ref - 1 : 2 * (Ref - 1) + Ref - 1) + offset;
        offset += 2 * (Ref - 1 + Ref - 1);
        return offset + (i - 1) + (Ref - 1) * (j - 1);
    }
    const int i = Idx % n, j = (Idx / n) % n, k = Idx / (n * n);
    const bool ibdr = i == 0 || i == Ref, jbdr = j == 0 || j == Ref, kbdr = k == 0 || k == Ref;
    const int nbdr = (ibdr ? 1 : 0) + (jbdr ? 1 : 0) + (kbdr ? 1 : 0);
    if (nbdr == 3)
        return (i ? (j ? 2 : 1) : (j ? 3 : 0)) + (k ? 4 : 0);
    int offset = 8;
    if (nbdr == 2) {
        if (!ibdr)
            return (i - 1) + (j ? Ref - 1 + Ref - 1 : 0) + (k ? 2 * (Ref - 1 + Ref - 1) : 0) +
                   offset;
        if (!jbdr)
            return (j - 1) + (i ? Ref - 1 : 2 * (Ref - 1) + Ref - 1) +
                   (k ? 2 * (Ref - 1 + Ref - 1) : 0) + offset;
        offset += 4 * (Ref - 1) + 4 * (Ref - 1);
        return (k - 1) + (Ref - 1) * (i ? (j ? 2 : 1) : (j ? 3 : 0)) + offset;
    }
    offset += 4 * (Ref - 1 + Ref - 1 + Ref - 1);
    if (nbdr == 1) {
        if (ibdr)
            return (j - 1) + (Ref - 1) * (k - 1) + (i ? (Ref - 1) * (Ref - 1) : 0) + offset;
        offset += 2 * (Ref - 1) * (Ref - 1);
        if (jbdr)
            return (i - 1) + (Ref - 1) * (k - 1) + (j ? (Ref - 1) * (Ref - 1) : 0) + offset;
        offset += 2 * (Ref - 1) * (Ref - 1);
        return (i - 1) + (Ref - 1) * (j - 1) + (k ? (Ref - 1) * (Ref - 1) : 0) + offset;
    }
    offset += 2 * 3 * (Ref - 1) * (Ref - 1);
    return offset + (i - 1) + (Ref - 1) * ((j - 1) + (Ref - 1) * (k - 1));
}

/// The nodes of an order-`P` VTK Lagrange cell, in VTK order, as integer
/// lattice coordinates (`x = i / P`).
inline std::vector<std::array<int, 3>> vtk_lattice(Shape S, int P) {
    std::vector<std::array<int, 3>> out(num_nodes(S, P));
    switch (S) {
        case Shape::Triangle: {
            int b[3];
            for (b[1] = 0; b[1] <= P; ++b[1])
                for (b[0] = 0; b[0] <= P - b[1]; ++b[0]) {
                    b[2] = P - b[0] - b[1];
                    out[static_cast<std::size_t>(vtk_triangle_index(b, P))] = {b[0], b[1], 0};
                }
            break;
        }
        case Shape::Tetra: {
            int b[4];
            for (b[2] = 0; b[2] <= P; ++b[2])
                for (b[1] = 0; b[1] <= P - b[2]; ++b[1])
                    for (b[0] = 0; b[0] <= P - b[1] - b[2]; ++b[0]) {
                        b[3] = P - b[0] - b[1] - b[2];
                        out[static_cast<std::size_t>(vtk_tetra_index(b, P))] = {b[0], b[1], b[2]};
                    }
            break;
        }
        case Shape::Wedge:
            for (int k = 0; k <= P; ++k)
                for (int j = 0; j <= P; ++j)
                    for (int i = 0; i <= P - j; ++i)
                        out[static_cast<std::size_t>(vtk_wedge_index(i, j, k, P))] = {i, j, k};
            break;
        default: {
            const int dim = shape_dim(S);
            const int n = P + 1;
            const int total = dim == 1 ? n : (dim == 2 ? n * n : n * n * n);
            for (int idx = 0; idx < total; ++idx) {
                const std::array<int, 3> ijk = {idx % n, dim > 1 ? (idx / n) % n : 0,
                                                dim > 2 ? idx / (n * n) : 0};
                out[static_cast<std::size_t>(vtk_tensor_index(idx, P, dim))] = ijk;
            }
            break;
        }
    }
    return out;
}

/// Corner weights of lattice node `rIjk` of an order-`P` cell, over the common
/// denominator `P^3`: `(corner, weight)` for every corner with a nonzero one,
/// by corner. Barycentric on simplices, multilinear on the square and cube,
/// their product on the prism -- so a node shared by two cells has the same
/// weights over the corners they share.
inline std::vector<std::pair<int, std::int64_t>> lattice_weights(Shape S, int P,
                                                                 const std::array<int, 3>& rIjk) {
    const std::int64_t p = P, i = rIjk[0], j = rIjk[1], k = rIjk[2];
    std::vector<std::int64_t> w;
    switch (S) {
        case Shape::Line:
            w = {(p - i) * p * p, i * p * p};
            break;
        case Shape::Triangle:
            w = {(p - i - j) * p * p, i * p * p, j * p * p};
            break;
        case Shape::Quad:
            w = {(p - i) * (p - j) * p, i * (p - j) * p, i * j * p, (p - i) * j * p};
            break;
        case Shape::Tetra:
            w = {(p - i - j - k) * p * p, i * p * p, j * p * p, k * p * p};
            break;
        case Shape::Hexahedron:
            w = {(p - i) * (p - j) * (p - k),
                 i * (p - j) * (p - k),
                 i * j * (p - k),
                 (p - i) * j * (p - k),
                 (p - i) * (p - j) * k,
                 i * (p - j) * k,
                 i * j * k,
                 (p - i) * j * k};
            break;
        case Shape::Wedge:
            w = {(p - i - j) * (p - k) * p, i * (p - k) * p, j * (p - k) * p,
                 (p - i - j) * k * p,       i * k * p,       j * k * p};
            break;
    }
    std::vector<std::pair<int, std::int64_t>> out;
    for (std::size_t c = 0; c < w.size(); ++c)
        if (w[c] != 0)
            out.emplace_back(static_cast<int>(c), w[c]);
    return out;
}

// --- orthogonal bases ---------------------------------------------------------------

/// Jacobi P_n^{(A,0)}(x) for n = 0..N.
inline std::vector<double> jacobi(int N, double A, double X) {
    std::vector<double> v(static_cast<std::size_t>(N) + 1);
    v[0] = 1.0;
    if (N >= 1)
        v[1] = ((A + 2.0) * X + A) / 2.0;
    for (int n = 1; n < N; ++n) {
        const double a1 = 2.0 * (n + 1) * (n + A + 1) * (2 * n + A);
        const double a2 = (2 * n + A + 1) * A * A;
        const double a3 = (2 * n + A) * (2 * n + A + 1) * (2 * n + A + 2);
        const double a4 = 2.0 * (n + A) * n * (2 * n + A + 2);
        v[static_cast<std::size_t>(n) + 1] = ((a2 + a3 * X) * v[static_cast<std::size_t>(n)] -
                                              a4 * v[static_cast<std::size_t>(n) - 1]) /
                                             a1;
    }
    return v;
}

/// The orthogonal basis of the cell's order-`P` space at reference point `rX`.
inline std::vector<double> basis(Shape S, int P, const std::array<double, 3>& rX) {
    std::vector<double> out;
    const double r = 2.0 * rX[0] - 1.0, s = 2.0 * rX[1] - 1.0, t = 2.0 * rX[2] - 1.0;
    switch (S) {
        case Shape::Line: {
            out = jacobi(P, 0.0, r);
            break;
        }
        case Shape::Quad: {
            const auto a = jacobi(P, 0.0, r), b = jacobi(P, 0.0, s);
            for (int j = 0; j <= P; ++j)
                for (int i = 0; i <= P; ++i)
                    out.push_back(a[static_cast<std::size_t>(i)] * b[static_cast<std::size_t>(j)]);
            break;
        }
        case Shape::Hexahedron: {
            const auto a = jacobi(P, 0.0, r), b = jacobi(P, 0.0, s), c = jacobi(P, 0.0, t);
            for (int k = 0; k <= P; ++k)
                for (int j = 0; j <= P; ++j)
                    for (int i = 0; i <= P; ++i)
                        out.push_back(a[static_cast<std::size_t>(i)] *
                                      b[static_cast<std::size_t>(j)] *
                                      c[static_cast<std::size_t>(k)]);
            break;
        }
        case Shape::Triangle:
        case Shape::Wedge: {
            const double a = std::fabs(1.0 - s) > 1e-14 ? 2.0 * (1.0 + r) / (1.0 - s) - 1.0 : -1.0;
            const auto pa = jacobi(P, 0.0, a);
            std::vector<double> tri;
            for (int i = 0; i <= P; ++i) {
                const auto pb = jacobi(P - i, 2.0 * i + 1.0, s);
                const double f = std::pow((1.0 - s) / 2.0, i);
                for (int j = 0; i + j <= P; ++j)
                    tri.push_back(pa[static_cast<std::size_t>(i)] * f *
                                  pb[static_cast<std::size_t>(j)]);
            }
            if (S == Shape::Triangle) {
                out = std::move(tri);
            } else {
                const auto c = jacobi(P, 0.0, t);
                for (int k = 0; k <= P; ++k)
                    for (double v : tri)
                        out.push_back(v * c[static_cast<std::size_t>(k)]);
            }
            break;
        }
        case Shape::Tetra: {
            const double a = std::fabs(s + t) > 1e-14 ? 2.0 * (1.0 + r) / (-s - t) - 1.0 : -1.0;
            const double b = std::fabs(1.0 - t) > 1e-14 ? 2.0 * (1.0 + s) / (1.0 - t) - 1.0 : -1.0;
            const auto pa = jacobi(P, 0.0, a);
            for (int i = 0; i <= P; ++i) {
                const auto pb = jacobi(P - i, 2.0 * i + 1.0, b);
                const double fb = std::pow((1.0 - b) / 2.0, i);
                for (int j = 0; i + j <= P; ++j) {
                    const auto pc = jacobi(P - i - j, 2.0 * (i + j) + 2.0, t);
                    const double fc = std::pow((1.0 - t) / 2.0, i + j);
                    for (int k = 0; i + j + k <= P; ++k)
                        out.push_back(pa[static_cast<std::size_t>(i)] * fb *
                                      pb[static_cast<std::size_t>(j)] * fc *
                                      pc[static_cast<std::size_t>(k)]);
                }
            }
            break;
        }
    }
    return out;
}

/// The matrix (row-major, targets x nodes) mapping values at `rNodes` -- a
/// unisolvent node set of the order-`P` space -- to values at `rTargets`.
inline std::vector<double> interpolation_matrix(
    Shape S, int P, const std::vector<std::array<double, 3>>& rNodes,
    const std::vector<std::array<double, 3>>& rTargets) {
    const std::size_t n = rNodes.size();
    if (n != num_nodes(S, P))
        throw std::runtime_error("lagrange: node count does not match the space");
    // A = V^T (n x n): A[b][m] = basis_b(node_m); solve A X = Phi^T for X
    // (n x targets); the matrix is X^T.
    std::vector<double> a(n * n);
    for (std::size_t m = 0; m < n; ++m) {
        const auto v = basis(S, P, rNodes[m]);
        for (std::size_t b = 0; b < n; ++b)
            a[b * n + m] = v[b];
    }
    const std::size_t nt = rTargets.size();
    std::vector<double> x(n * nt);
    for (std::size_t t = 0; t < nt; ++t) {
        const auto v = basis(S, P, rTargets[t]);
        for (std::size_t b = 0; b < n; ++b)
            x[b * nt + t] = v[b];
    }
    // LU with partial pivoting, applied to every right-hand side at once.
    for (std::size_t c = 0; c < n; ++c) {
        std::size_t piv = c;
        for (std::size_t r = c + 1; r < n; ++r)
            if (std::fabs(a[r * n + c]) > std::fabs(a[piv * n + c]))
                piv = r;
        if (std::fabs(a[piv * n + c]) < 1e-300)
            throw std::runtime_error("lagrange: the node set is not unisolvent");
        if (piv != c) {
            for (std::size_t k = 0; k < n; ++k)
                std::swap(a[c * n + k], a[piv * n + k]);
            for (std::size_t k = 0; k < nt; ++k)
                std::swap(x[c * nt + k], x[piv * nt + k]);
        }
        for (std::size_t r = c + 1; r < n; ++r) {
            const double f = a[r * n + c] / a[c * n + c];
            if (f == 0.0)
                continue;
            for (std::size_t k = c; k < n; ++k)
                a[r * n + k] -= f * a[c * n + k];
            for (std::size_t k = 0; k < nt; ++k)
                x[r * nt + k] -= f * x[c * nt + k];
        }
    }
    for (std::size_t c = n; c-- > 0;) {
        for (std::size_t k = 0; k < nt; ++k) {
            double v = x[c * nt + k];
            for (std::size_t q = c + 1; q < n; ++q)
                v -= a[c * n + q] * x[q * nt + k];
            x[c * nt + k] = v / a[c * n + c];
        }
    }
    std::vector<double> out(nt * n);
    for (std::size_t t = 0; t < nt; ++t)
        for (std::size_t m = 0; m < n; ++m)
            out[t * n + m] = x[m * nt + t];
    // Snap exact reproductions (a target that is a node) to 0/1.
    for (double& v : out)
        if (std::fabs(v) < 1e-14)
            v = 0.0;
        else if (std::fabs(v - 1.0) < 1e-14)
            v = 1.0;
    return out;
}

}  // namespace lagrange
}  // namespace meshioplusplus
