// ===== begin src/cpp/src/operations/transform.cpp =====
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

// A deep copy of an NDArray that always owns its buffer (the source may be a
// view over foreign memory, e.g. numpy memory on the write path).
NDArray transform_owned_copy(const NDArray& rArr) {
    NDArray c = rArr;
    c.MakeOwned();
    return c;
}

// Determinant of the 3x3 linear block of a row-major 4x4 matrix.
double transform_linear_det(const std::array<double, 16>& rM) {
    const double a = rM[0], b = rM[1], c = rM[2];
    const double d = rM[4], e = rM[5], f = rM[6];
    const double g = rM[8], h = rM[9], i = rM[10];
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

// Multiply the row-major 4x4 `rA` by `rB` (result = A * B).
std::array<double, 16> transform_matmul(const std::array<double, 16>& rA,
                                        const std::array<double, 16>& rB) {
    std::array<double, 16> out = {};
    for (std::size_t r = 0; r < 4; ++r)
        for (std::size_t c = 0; c < 4; ++c) {
            double s = 0.0;
            for (std::size_t k = 0; k < 4; ++k)
                s += rA[r * 4 + k] * rB[k * 4 + c];
            out[r * 4 + c] = s;
        }
    return out;
}

// Transform the point coordinates into a fresh array of the same dtype.
NDArray transform_apply_points(const NDArray& rPoints, std::size_t n, std::size_t dim,
                               const std::array<double, 16>& rM) {
    NDArray out = NDArray::Uninit(rPoints.Dtype(), {n, dim});
    if (n == 0 || dim == 0)
        return out;
    detail::dispatch_dtype(rPoints.Dtype(), [&]<class T>() {
        const T* src = rPoints.As<T>();
        T* dst = out.As<T>();
        parallel_for_bw(n, [&](std::size_t i) {
            const std::size_t base = i * dim;
            const double x = dim > 0 ? static_cast<double>(src[base + 0]) : 0.0;
            const double y = dim > 1 ? static_cast<double>(src[base + 1]) : 0.0;
            const double z = dim > 2 ? static_cast<double>(src[base + 2]) : 0.0;
            const double nx = rM[0] * x + rM[1] * y + rM[2] * z + rM[3];
            const double ny = rM[4] * x + rM[5] * y + rM[6] * z + rM[7];
            const double nz = rM[8] * x + rM[9] * y + rM[10] * z + rM[11];
            if (dim > 0)
                dst[base + 0] = static_cast<T>(nx);
            if (dim > 1)
                dst[base + 1] = static_cast<T>(ny);
            if (dim > 2)
                dst[base + 2] = static_cast<T>(nz);
        });
    });
    return out;
}

// Rotate vector (cols == 3) or tensor (cols == 9, row-major 3x3) rows of a
// float point_data array by the 3x3 linear block `rR` (v' = R v, A' = R A R^T).
// Returns a fresh array of the same dtype. Only Float32/Float64 arrays qualify.
NDArray transform_rotate_point_data(const NDArray& rArr, std::size_t n, std::size_t cols,
                                    const std::array<double, 9>& rR) {
    NDArray out = transform_owned_copy(rArr);
    detail::dispatch_dtype(rArr.Dtype(), [&]<class T>() {
        T* p = out.As<T>();
        if (cols == 3) {
            parallel_for_bw(n, [&](std::size_t i) {
                const std::size_t b = i * 3;
                const double v0 = static_cast<double>(p[b + 0]);
                const double v1 = static_cast<double>(p[b + 1]);
                const double v2 = static_cast<double>(p[b + 2]);
                p[b + 0] = static_cast<T>(rR[0] * v0 + rR[1] * v1 + rR[2] * v2);
                p[b + 1] = static_cast<T>(rR[3] * v0 + rR[4] * v1 + rR[5] * v2);
                p[b + 2] = static_cast<T>(rR[6] * v0 + rR[7] * v1 + rR[8] * v2);
            });
        } else {  // cols == 9 : A' = R A R^T
            parallel_for_bw(n, [&](std::size_t i) {
                const std::size_t b = i * 9;
                double a[9];
                for (std::size_t k = 0; k < 9; ++k)
                    a[k] = static_cast<double>(p[b + k]);
                // tmp = R * A
                double tmp[9];
                for (std::size_t r = 0; r < 3; ++r)
                    for (std::size_t c = 0; c < 3; ++c)
                        tmp[r * 3 + c] = rR[r * 3 + 0] * a[0 * 3 + c] +
                                         rR[r * 3 + 1] * a[1 * 3 + c] +
                                         rR[r * 3 + 2] * a[2 * 3 + c];
                // out = tmp * R^T
                for (std::size_t r = 0; r < 3; ++r)
                    for (std::size_t c = 0; c < 3; ++c)
                        p[b + r * 3 + c] = static_cast<T>(tmp[r * 3 + 0] * rR[c * 3 + 0] +
                                                          tmp[r * 3 + 1] * rR[c * 3 + 1] +
                                                          tmp[r * 3 + 2] * rR[c * 3 + 2]);
            });
        }
    });
    return out;
}

bool transform_is_float(DType dt) {
    return dt == DType::Float32 || dt == DType::Float64;
}

}  // namespace

AffineTransform transform_translation(double dx, double dy, double dz) {
    AffineTransform t;
    t.mMatrix[3] = dx;
    t.mMatrix[7] = dy;
    t.mMatrix[11] = dz;
    return t;
}

AffineTransform transform_scale(double sx, double sy, double sz) {
    AffineTransform t;
    t.mMatrix[0] = sx;
    t.mMatrix[5] = sy;
    t.mMatrix[10] = sz;
    return t;
}

AffineTransform transform_units(double factor) {
    return transform_scale(factor, factor, factor);
}

AffineTransform transform_rotation(double ax, double ay, double az, double angle_rad) {
    const double len = std::sqrt(ax * ax + ay * ay + az * az);
    if (len < 1e-300)
        throw std::invalid_argument("transform: rotation axis is zero-length");
    const double x = ax / len, y = ay / len, z = az / len;
    const double c = std::cos(angle_rad), s = std::sin(angle_rad), t = 1.0 - c;
    AffineTransform out;
    auto& m = out.mMatrix;
    m[0] = t * x * x + c;
    m[1] = t * x * y - s * z;
    m[2] = t * x * z + s * y;
    m[4] = t * x * y + s * z;
    m[5] = t * y * y + c;
    m[6] = t * y * z - s * x;
    m[8] = t * x * z - s * y;
    m[9] = t * y * z + s * x;
    m[10] = t * z * z + c;
    return out;
}

AffineTransform transform_from_matrix(const double* pMatrix16) {
    AffineTransform out;
    for (std::size_t i = 0; i < 16; ++i)
        out.mMatrix[i] = pMatrix16[i];
    return out;
}

AffineTransform transform_compose(const AffineTransform& rSecond, const AffineTransform& rFirst) {
    AffineTransform out;
    out.mMatrix = transform_matmul(rSecond.mMatrix, rFirst.mMatrix);
    return out;
}

Mesh transform(const Mesh& rMesh, const AffineTransform& rXform, bool rotate_vector_data) {
    const std::array<double, 16>& M = rXform.mMatrix;
    if (transform_linear_det(M) < 0.0)
        log::warn(
            "transform: orientation-reversing (negative determinant); cell orientation "
            "may be flipped");

    Mesh out;

    // Points (transformed, dtype preserved).
    const std::size_t n = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();
    out.AssignPoints(transform_apply_points(rMesh.Points(), n, dim, M));

    // Cells (clone; rectangular / polygon / polyhedron).
    for (const auto cb : rMesh.CellRange()) {
        if (cb.IsPolyhedron()) {
            std::vector<std::vector<std::vector<std::int64_t>>> cells(cb.NumCells());
            for (std::size_t c = 0; c < cb.NumCells(); ++c) {
                cells[c].resize(cb.NumFaces(c));
                for (std::size_t f = 0; f < cb.NumFaces(c); ++f) {
                    auto face = cb.Face(c, f);
                    cells[c][f].assign(face.first, face.first + face.second);
                }
            }
            out.AddPolyhedronBlock(std::string(cb.Type()), std::move(cells));
        } else if (cb.IsRagged()) {
            std::vector<std::vector<std::int64_t>> rows(cb.NumCells());
            for (std::size_t c = 0; c < cb.NumCells(); ++c)
                rows[c].assign(cb.Row(c), cb.Row(c) + cb.RowSize(c));
            out.AddPolygonBlock(std::string(cb.Type()), std::move(rows));
        } else {
            out.AddCellBlock(std::string(cb.Type()), transform_owned_copy(cb.Conn()));
        }
    }

    // Point data (optionally rotate vector/tensor float arrays).
    const std::array<double, 9> R = {M[0], M[1], M[2], M[4], M[5], M[6], M[8], M[9], M[10]};
    for (const std::string& name : rMesh.PointDataNames()) {
        const NDArray& a = rMesh.PointData(name);
        const std::size_t cols = n > 0 ? a.Size() / n : 0;
        if (rotate_vector_data && transform_is_float(a.Dtype()) && n > 0 &&
            (cols == 3 || cols == 9))
            out.AddPointData(name, transform_rotate_point_data(a, n, cols, R));
        else
            out.AddPointData(name, transform_owned_copy(a));
    }

    // Cell data (optionally rotated too -- a vector living on a cell rotates
    // exactly as one living on a point does; the block's row count is its own
    // cell count, so each block is widened independently).
    std::vector<std::size_t> cell_counts;
    for (const auto cb : rMesh.CellRange())
        cell_counts.push_back(cb.NumCells());
    for (const std::string& name : rMesh.CellDataNames()) {
        std::vector<NDArray> blocks;
        for (std::size_t b = 0; b < rMesh.CellDataNumBlocks(name); ++b) {
            const NDArray& a = rMesh.CellData(name, b);
            const std::size_t rows = b < cell_counts.size() ? cell_counts[b] : 0;
            const std::size_t cols = rows > 0 ? a.Size() / rows : 0;
            if (rotate_vector_data && transform_is_float(a.Dtype()) && rows > 0 &&
                (cols == 3 || cols == 9))
                blocks.push_back(transform_rotate_point_data(a, rows, cols, R));
            else
                blocks.push_back(transform_owned_copy(a));
        }
        out.AddCellData(name, std::move(blocks));
    }
    for (const std::string& name : rMesh.FieldDataNames())
        out.AddFieldData(name, transform_owned_copy(rMesh.FieldData(name)));

    // Named regions pass through verbatim: a transform moves coordinates and
    // renumbers nothing, so every point, cell and facet index still names the
    // same entity.
    for (std::size_t i = 0; i < rMesh.NumRegions(); ++i)
        out.AddRegion(rMesh.Region(i));
    // Property sets ride along too: these operations preserve the mesh's shape,
    // so dropping a deck's material data here would be new lossiness. They are
    // keyed by id, not by entity index, so there is nothing to remap.
    for (std::size_t i = 0; i < rMesh.NumPropertySets(); ++i)
        out.AddPropertySet(rMesh.GetPropertySet(i));

    return out;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/transform.cpp =====
// ===== begin src/cpp/src/operations/undo_green.cpp =====
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kUgPrefix = "meshio++: undo_green: ";

// Read a required Int64 scalar cell_data array (one value per cell, covering
// every block) into a flat global-cell-order vector. Throws by name on any
// mismatch -- undo_green's fine-mesh preconditions are hard requirements,
// unlike detail::refine_read_hierarchy's warn-and-fall-back contract.
std::vector<std::int64_t> ug_read_required(const Mesh& rMesh,
                                           const std::vector<std::int64_t>& rBases,
                                           const char* pName) {
    if (!rMesh.HasCellData(pName))
        throw std::invalid_argument(
            std::string(kUgPrefix) + "the fine mesh has no '" + pName +
            "' cell_data; run refine(..., record_hierarchy=True, record_levels=True) first");
    const std::size_t nblocks = rMesh.NumCellBlocks();
    if (rMesh.CellDataNumBlocks(pName) != nblocks)
        throw std::invalid_argument(std::string(kUgPrefix) + "'" + pName +
                                    "' does not cover every cell block");
    std::vector<std::int64_t> out(static_cast<std::size_t>(detail::total_cells(rBases)));
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::size_t base = static_cast<std::size_t>(rBases[bi]);
        const std::size_t ncells = cb.NumCells();
        const NDArray& a = rMesh.CellData(pName, bi);
        if (detail::rows(a) != ncells || (ncells != 0 && a.Size() / ncells != 1))
            throw std::invalid_argument(std::string(kUgPrefix) + "'" + pName + "' block " +
                                        std::to_string(bi) + " is not one scalar value per cell");
        for (std::size_t c = 0; c < ncells; ++c)
            out[base + c] = detail::read_int(a, c);
        ++bi;
    }
    return out;
}

// Same shape check, but returns empty rather than throwing when `pName` is
// absent or malformed -- used for the coarse mesh's OPTIONAL refine:level,
// where absence means "never refined" (implicit level 0 for every cell).
std::vector<std::int64_t> ug_read_optional(const Mesh& rMesh,
                                           const std::vector<std::int64_t>& rBases,
                                           const char* pName) {
    if (!rMesh.HasCellData(pName))
        return {};
    const std::size_t nblocks = rMesh.NumCellBlocks();
    if (rMesh.CellDataNumBlocks(pName) != nblocks)
        return {};
    std::vector<std::int64_t> out(static_cast<std::size_t>(detail::total_cells(rBases)));
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::size_t base = static_cast<std::size_t>(rBases[bi]);
        const std::size_t ncells = cb.NumCells();
        const NDArray& a = rMesh.CellData(pName, bi);
        if (detail::rows(a) != ncells || (ncells != 0 && a.Size() / ncells != 1))
            return {};
        for (std::size_t c = 0; c < ncells; ++c)
            out[base + c] = detail::read_int(a, c);
        ++bi;
    }
    return out;
}

// Whether a name is one of the six reserved refine:* arrays -- always
// excluded from undo_green's output (stale hierarchy bookkeeping).
bool ug_is_reserved(const std::string& rName) {
    return rName == kRefineParentCellName || rName == kRefineLevelName ||
           rName == kRefineHangingName || rName == kRefineEntityName ||
           rName == kRefineCellIdName || rName == kRefineParentIdName;
}

// A cell's role in the output, decided once per sibling group.
enum class UgRole { Keep, AnchorSubstitute, Suppressed };

}  // namespace

UndoGreenResult undo_green(const Mesh& rCoarse, const Mesh& rFine) {
    if (rCoarse.NumPoints() > rFine.NumPoints())
        throw std::invalid_argument(
            std::string(kUgPrefix) +
            "the coarse mesh has more points than the fine mesh, so they cannot be the "
            "coarse/fine pair of one refine() call");

    const std::vector<std::int64_t> fine_bases = detail::block_bases(rFine);
    const std::vector<std::int64_t> coarse_bases = detail::block_bases(rCoarse);
    const auto total_fine = static_cast<std::size_t>(detail::total_cells(fine_bases));

    const std::vector<std::int64_t> fine_id =
        ug_read_required(rFine, fine_bases, kRefineCellIdName);
    const std::vector<std::int64_t> fine_parent =
        ug_read_required(rFine, fine_bases, kRefineParentIdName);
    const std::vector<std::int64_t> fine_level =
        ug_read_required(rFine, fine_bases, kRefineLevelName);

    // --- resolve the coarse mesh's id space: its own recorded ids if valid,
    // else the implicit global-block-major ids -- refine_attach_hierarchy's
    // own "start fresh" fallback. --------------------------------------------
    std::vector<std::int64_t> coarse_ids;
    std::int64_t coarse_id_base = 0;
    const detail::RefineHierarchyState state =
        detail::refine_read_hierarchy(rCoarse, coarse_bases, coarse_ids, coarse_id_base);
    if (state != detail::RefineHierarchyState::Valid) {
        const auto total_coarse = static_cast<std::size_t>(detail::total_cells(coarse_bases));
        coarse_ids.resize(total_coarse);
        for (std::size_t i = 0; i < total_coarse; ++i)
            coarse_ids[i] = static_cast<std::int64_t>(i);
    }
    std::unordered_map<std::int64_t, std::int64_t> id_to_coarse_row;
    id_to_coarse_row.reserve(coarse_ids.size());
    for (std::size_t i = 0; i < coarse_ids.size(); ++i)
        id_to_coarse_row[coarse_ids[i]] = static_cast<std::int64_t>(i);

    const std::vector<std::int64_t> coarse_level =
        ug_read_optional(rCoarse, coarse_bases, kRefineLevelName);
    auto coarse_level_at = [&](std::int64_t row) -> std::int64_t {
        return coarse_level.empty() ? 0 : coarse_level[static_cast<std::size_t>(row)];
    };

    // --- group fine cells by parent_id --------------------------------------
    std::unordered_map<std::int64_t, std::vector<std::int64_t>> groups_by_parent;
    for (std::size_t g = 0; g < total_fine; ++g)
        groups_by_parent[fine_parent[g]].push_back(static_cast<std::int64_t>(g));

    // --- classify every global fine cell's role; for green groups, resolve
    // the substitution source once ------------------------------------------
    std::vector<UgRole> role(total_fine, UgRole::Keep);
    std::vector<std::int64_t> group_id_of(total_fine, -1);
    std::vector<std::int64_t> group_coarse_row;  // indexed by green group id
    std::vector<std::int64_t> group_size;        // indexed by green group id
    std::int64_t next_group_id = 0;

    for (auto& entry : groups_by_parent) {
        const std::int64_t parent_id = entry.first;
        std::vector<std::int64_t>& members = entry.second;
        std::sort(members.begin(), members.end());

        if (members.size() == 1) {
            const std::int64_t g = members.front();
            if (fine_id[static_cast<std::size_t>(g)] != parent_id)
                throw std::invalid_argument(
                    std::string(kUgPrefix) +
                    "malformed hierarchy: a singleton sibling group's refine:cell_id does not "
                    "equal its refine:parent_id (cell " +
                    std::to_string(g) + ")");
            continue;  // untouched: role stays Keep
        }

        const auto it = id_to_coarse_row.find(parent_id);
        if (it == id_to_coarse_row.end())
            throw std::invalid_argument(
                std::string(kUgPrefix) + "refine:parent_id " + std::to_string(parent_id) +
                " does not resolve in the coarse mesh's id space -- these two meshes are not "
                "the coarse/fine pair of one refine() call");
        const std::int64_t coarse_row = it->second;
        const std::int64_t clevel = coarse_level_at(coarse_row);

        const std::int64_t flevel = fine_level[static_cast<std::size_t>(members.front())];
        for (std::int64_t g : members)
            if (fine_level[static_cast<std::size_t>(g)] != flevel)
                throw std::invalid_argument(
                    std::string(kUgPrefix) +
                    "malformed hierarchy: the sibling group under refine:parent_id " +
                    std::to_string(parent_id) + " does not agree on refine:level");

        if (flevel == clevel + 1)
            continue;  // red: a genuine refinement, kept unchanged (role stays Keep)

        if (flevel > clevel + 1)
            throw std::invalid_argument(
                std::string(kUgPrefix) + "the sibling group under refine:parent_id " +
                std::to_string(parent_id) + " has refine:level " + std::to_string(flevel) +
                ", more than one deeper than its coarse parent's own level (" +
                std::to_string(clevel) +
                "); undo_green only supports a single-pass (levels=1) hierarchy");

        if (flevel != clevel)
            throw std::invalid_argument(
                std::string(kUgPrefix) + "the sibling group under refine:parent_id " +
                std::to_string(parent_id) + " has refine:level " + std::to_string(flevel) +
                ", which is neither its coarse parent's own level (" + std::to_string(clevel) +
                ", green) nor one more (" + std::to_string(clevel + 1) + ", red)");

        // green: substitute the whole group with one row from the coarse mesh
        const std::int64_t gid = next_group_id++;
        group_coarse_row.push_back(coarse_row);
        group_size.push_back(static_cast<std::int64_t>(members.size()));
        role[static_cast<std::size_t>(members.front())] = UgRole::AnchorSubstitute;
        group_id_of[static_cast<std::size_t>(members.front())] = gid;
        for (std::size_t k = 1; k < members.size(); ++k) {
            role[static_cast<std::size_t>(members[static_cast<std::ptrdiff_t>(k)])] =
                UgRole::Suppressed;
            group_id_of[static_cast<std::size_t>(members[static_cast<std::ptrdiff_t>(k)])] = gid;
        }
    }

    // --- build the output mesh: fine's own block structure, unchanged types
    // and order, rows compacted/substituted -----------------------------------
    Mesh out;
    out.AssignPoints(detail::data_owned_copy(rFine.Points()));

    const std::size_t nblocks = rFine.NumCellBlocks();
    std::vector<std::size_t> out_ncells(nblocks, 0);
    {
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] != UgRole::Suppressed)
                    ++out_ncells[bi];
            }
            ++bi;
        }
    }

    std::vector<NDArray> cell_maps(nblocks);
    std::vector<NDArray> out_conn(nblocks);
    std::vector<std::int64_t> group_output_global(static_cast<std::size_t>(next_group_id), -1);
    std::vector<std::size_t> group_fine_block(static_cast<std::size_t>(next_group_id), 0);

    {
        std::size_t bi = 0;
        std::int64_t out_block_base = 0;
        for (const auto cb : rFine.CellRange()) {
            const std::size_t npc = cb.NodesPerCell();
            NDArray conn = NDArray::Uninit(DType::Int64, {out_ncells[bi], npc});
            std::int64_t* dst = conn.As<std::int64_t>();
            NDArray cmap = NDArray::Uninit(DType::Int64, {cb.NumCells()});
            std::int64_t* cm = cmap.As<std::int64_t>();

            std::size_t out_row = 0;
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] == UgRole::Suppressed) {
                    const std::int64_t gid = group_id_of[g];
                    cm[r] = group_output_global[static_cast<std::size_t>(gid)];
                    continue;
                }
                if (role[g] == UgRole::Keep) {
                    const NDArray& src = cb.Conn();
                    for (std::size_t k = 0; k < npc; ++k)
                        dst[out_row * npc + k] = detail::read_int(src, r * npc + k);
                } else {  // AnchorSubstitute
                    const std::int64_t gid = group_id_of[g];
                    const std::int64_t coarse_row = group_coarse_row[static_cast<std::size_t>(gid)];
                    const auto blk_row = detail::global_to_block_row(coarse_bases, coarse_row);
                    const auto ccb = rCoarse.Cells(blk_row.first);
                    const NDArray& csrc = ccb.Conn();
                    for (std::size_t k = 0; k < npc; ++k)
                        dst[out_row * npc + k] = detail::read_int(
                            csrc, static_cast<std::size_t>(blk_row.second) * npc + k);
                    group_output_global[static_cast<std::size_t>(gid)] =
                        out_block_base + static_cast<std::int64_t>(out_row);
                    group_fine_block[static_cast<std::size_t>(gid)] = bi;
                }
                cm[r] = out_block_base + static_cast<std::int64_t>(out_row);
                ++out_row;
            }

            out_conn[bi] = std::move(conn);
            cell_maps[bi] = std::move(cmap);
            out_block_base += static_cast<std::int64_t>(out_ncells[bi]);
            ++bi;
        }
    }

    {
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            out.AddCellBlock(std::string(cb.Type()), std::move(out_conn[bi]));
            ++bi;
        }
    }

    // --- point_data / field_data: unchanged, no new or pruned points --------
    // (refine:entity / refine:hanging are POINT data, not cell_data, but are
    // just as much stale hierarchy bookkeeping as the four cell_data ones --
    // ug_is_reserved covers all six, so this loop must consult it too)
    for (const std::string& name : rFine.PointDataNames()) {
        if (ug_is_reserved(name))
            continue;
        out.AddPointData(name, detail::data_owned_copy(rFine.PointData(name)));
    }
    for (const std::string& name : rFine.FieldDataNames())
        out.AddFieldData(name, detail::data_owned_copy(rFine.FieldData(name)));

    // --- cell_data: reserved refine:* arrays dropped; everything else kept
    // (fine's own row for Keep, coarse's for AnchorSubstitute) ---------------
    for (const std::string& name : rFine.CellDataNames()) {
        if (ug_is_reserved(name))
            continue;
        if (rFine.CellDataNumBlocks(name) != nblocks) {
            log::warn(
                "{}cell_data '{}' does not have one array per fine block; dropped rather than "
                "guessed at",
                kUgPrefix, name);
            continue;
        }

        // Pre-check every green group's substitution source before touching
        // anything, so a bad array is dropped whole rather than half-built.
        bool ok = true;
        if (next_group_id > 0) {
            if (!rCoarse.HasCellData(name) ||
                rCoarse.CellDataNumBlocks(name) != rCoarse.NumCellBlocks()) {
                ok = false;
            } else {
                for (std::int64_t gid = 0; ok && gid < next_group_id; ++gid) {
                    const auto ug = static_cast<std::size_t>(gid);
                    const auto blk_row =
                        detail::global_to_block_row(coarse_bases, group_coarse_row[ug]);
                    const NDArray& fsrc = rFine.CellData(name, group_fine_block[ug]);
                    const NDArray& csrc = rCoarse.CellData(name, blk_row.first);
                    const std::size_t f_row_bytes =
                        fsrc.Nbytes() / std::max<std::size_t>(1, detail::rows(fsrc));
                    const std::size_t c_row_bytes =
                        csrc.Nbytes() / std::max<std::size_t>(1, detail::rows(csrc));
                    if (fsrc.Dtype() != csrc.Dtype() || f_row_bytes != c_row_bytes)
                        ok = false;
                }
            }
        }
        if (!ok) {
            log::warn(
                "{}cell_data '{}' cannot be honestly restored for a substituted cell (missing, "
                "incomplete or a different shape/dtype on the coarse mesh); dropped",
                kUgPrefix, name);
            continue;
        }

        std::vector<NDArray> out_blocks(nblocks);
        std::size_t bi = 0;
        for (const auto cb : rFine.CellRange()) {
            const NDArray& fsrc = rFine.CellData(name, bi);
            std::vector<std::size_t> shape = fsrc.Shape();
            shape[0] = out_ncells[bi];
            NDArray dst = NDArray::Uninit(fsrc.Dtype(), shape);
            const std::size_t row_bytes =
                fsrc.Nbytes() / std::max<std::size_t>(1, detail::rows(fsrc));
            std::byte* p_dst = dst.Data();
            const std::byte* p_fsrc = fsrc.Data();

            std::size_t out_row = 0;
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::size_t g = static_cast<std::size_t>(fine_bases[bi]) + r;
                if (role[g] == UgRole::Suppressed)
                    continue;
                if (role[g] == UgRole::Keep) {
                    std::memcpy(p_dst + out_row * row_bytes, p_fsrc + r * row_bytes, row_bytes);
                } else {  // AnchorSubstitute
                    const std::int64_t gid = group_id_of[g];
                    const auto ug = static_cast<std::size_t>(gid);
                    const auto blk_row =
                        detail::global_to_block_row(coarse_bases, group_coarse_row[ug]);
                    const NDArray& csrc = rCoarse.CellData(name, blk_row.first);
                    std::memcpy(p_dst + out_row * row_bytes,
                                csrc.Data() + static_cast<std::size_t>(blk_row.second) * row_bytes,
                                row_bytes);
                }
                ++out_row;
            }
            out_blocks[bi] = std::move(dst);
            ++bi;
        }
        out.AddCellData(name, std::move(out_blocks));
    }

    UndoGreenResult res;
    res.mMesh = std::move(out);
    res.mCellMaps = std::move(cell_maps);
    res.mNumGroupsUndone = next_group_id;
    std::int64_t removed = 0;
    for (std::int64_t sz : group_size)
        removed += sz - 1;
    res.mNumCellsRemoved = removed;

    detail::RegionRemap rmap;
    rmap.mCellMapKind = detail::CellMapKind::Direct;
    rmap.pCellMaps = &res.mCellMaps;
    rmap.mDropSideRegions = true;
    rmap.mOpName = "undo_green";
    detail::remap_regions(rFine, res.mMesh, rmap);

    return res;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/undo_green.cpp =====
// ===== begin src/cpp/src/operations/voxelize.cpp =====
#include <algorithm>
#include <array>
#include <cmath>
#include <cstring>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kVoxPrefix = "meshio++: voxelize: ";

// The cell budget check for grid(), which has no LatticeRequest to resolve. It
// is a *named* refusal rather than an allocation failure because the failure
// mode it guards is mundane and predictable: 512^3 is 134 million cells and
// ~11.8 GB of points and connectivity, which a user asks for by typo far more
// often than on purpose. `lattice_resolve` applies the identical rule (and the
// identical message) to the request-shaped callers.
void vox_check_budget(std::int64_t Cells, std::int64_t MaxCells, const char* pPrefix) {
    if (MaxCells <= 0 || Cells <= MaxCells)
        return;
    throw std::invalid_argument(std::string(pPrefix) + "the requested grid has " +
                                std::to_string(Cells) + " cells, above the limit of " +
                                std::to_string(MaxCells) +
                                " (raise max_cells, coarsen the resolution, or use a band)");
}

// The lattice a voxelization runs on. Exactly one of resolution and cell size
// must be given: defaulting one of them would silently pick a grid the caller
// did not choose, and for an object whose cost is cubic in that choice that is
// not a kindness. The rule itself lives in detail/grid_lattice.hpp, since
// `compute_sdf` resolves the identical six fields the identical way.
detail::LatticeSpec vox_resolve_lattice(const Mesh& rMesh, const VoxelOptions& rOptions) {
    detail::LatticeRequest req;
    req.mResolution = rOptions.mResolution;
    req.mCellSize = rOptions.mCellSize;
    req.mBounds = rOptions.mBounds;
    req.mPadding = rOptions.mPadding;
    req.mPaddingRelative = rOptions.mPaddingRelative;
    req.mMaxCells = rOptions.mMaxCells;
    return detail::lattice_resolve(rMesh, req, kVoxPrefix);
}

// Which cells the fill rule keeps, as a per-cell flag. An empty result means
// "all of them", which lets the caller skip the subsetting pass entirely.
std::vector<char> vox_occupancy(const Mesh& rMesh, const detail::LatticeSpec& rSpec,
                                const VoxelOptions& rOptions) {
    if (rOptions.mFill == VoxelFill::All)
        return {};

    const std::int64_t ncells = detail::lattice_num_cells(rSpec);
    std::vector<char> occupied(static_cast<std::size_t>(ncells), 0);
    const std::int64_t nx = rSpec.mDims[0];
    const std::int64_t ny = rSpec.mDims[1];

    if (rOptions.mFill == VoxelFill::Surface) {
        // Exact triangle/box overlap, not a bounding-box test: a long diagonal
        // triangle overlaps far more boxes than it enters.
        const detail::TriangleSoup soup =
            detail::build_triangle_soup(rMesh, rOptions.mDistance.mSurfaceRegion);
        const detail::Vec3 half{
            {rSpec.mSpacing[0] * 0.5, rSpec.mSpacing[1] * 0.5, rSpec.mSpacing[2] * 0.5}};
        // Serial over triangles, each touching only the voxels of its own
        // bounding box: a parallel pass would race on the shared flag array for
        // no real gain, since the inner box is small.
        for (std::size_t t = 0; t < soup.NumTriangles(); ++t) {
            const detail::Vec3& a = soup.mCorners[t * 3 + 0];
            const detail::Vec3& b = soup.mCorners[t * 3 + 1];
            const detail::Vec3& c = soup.mCorners[t * 3 + 2];
            std::array<std::int64_t, 3> lo{}, hi{};
            bool skip = false;
            for (std::size_t k = 0; k < 3; ++k) {
                if (!(rSpec.mSpacing[k] > 0.0)) {
                    skip = true;
                    break;
                }
                const double tlo = std::min(a[k], std::min(b[k], c[k]));
                const double thi = std::max(a[k], std::max(b[k], c[k]));
                double flo = std::floor((tlo - rSpec.mOrigin[k]) / rSpec.mSpacing[k]);
                double fhi = std::floor((thi - rSpec.mOrigin[k]) / rSpec.mSpacing[k]);
                flo = flo < 0.0 ? 0.0 : flo;
                const double last = static_cast<double>(rSpec.mDims[k] - 1);
                fhi = fhi > last ? last : fhi;
                if (fhi < flo) {
                    skip = true;
                    break;
                }
                lo[k] = static_cast<std::int64_t>(flo);
                hi[k] = static_cast<std::int64_t>(fhi);
            }
            if (skip)
                continue;
            for (std::int64_t k = lo[2]; k <= hi[2]; ++k)
                for (std::int64_t j = lo[1]; j <= hi[1]; ++j)
                    for (std::int64_t i = lo[0]; i <= hi[0]; ++i) {
                        const std::int64_t cid = (k * ny + j) * nx + i;
                        if (occupied[static_cast<std::size_t>(cid)])
                            continue;
                        const detail::Vec3 centre{
                            {rSpec.mOrigin[0] + (static_cast<double>(i) + 0.5) * rSpec.mSpacing[0],
                             rSpec.mOrigin[1] + (static_cast<double>(j) + 0.5) * rSpec.mSpacing[1],
                             rSpec.mOrigin[2] +
                                 (static_cast<double>(k) + 0.5) * rSpec.mSpacing[2]}};
                        if (detail::tri_box_overlap(centre, half, a, b, c))
                            occupied[static_cast<std::size_t>(cid)] = 1;
                    }
        }
        return occupied;
    }

    // Inside: sign the distance at each cell centre. This is the only fill that
    // needs a closed surface, and it says so through the watertight check rather
    // than by quietly producing a hollow result.
    const detail::TriangleSoup soup =
        detail::build_triangle_soup(rMesh, rOptions.mDistance.mSurfaceRegion);
    std::vector<detail::Vec3> centres(static_cast<std::size_t>(ncells));
    parallel_for_bw(static_cast<std::size_t>(ncells), [&](std::size_t c) {
        const std::int64_t g = static_cast<std::int64_t>(c);
        const std::int64_t i = g % nx;
        const std::int64_t j = (g / nx) % ny;
        const std::int64_t k = g / (nx * ny);
        centres[c] =
            detail::Vec3{{rSpec.mOrigin[0] + (static_cast<double>(i) + 0.5) * rSpec.mSpacing[0],
                          rSpec.mOrigin[1] + (static_cast<double>(j) + 0.5) * rSpec.mSpacing[1],
                          rSpec.mOrigin[2] + (static_cast<double>(k) + 0.5) * rSpec.mSpacing[2]}};
    });

    SurfaceDistanceOptions dopts = rOptions.mDistance;
    if (dopts.mSign == SdfSign::Unsigned)
        throw std::invalid_argument(std::string(kVoxPrefix) +
                                    "fill 'inside' needs a sign, but sign='unsigned' was given");
    dopts.mBand = 0.0;  // a band would clamp the very sign this fill depends on
    const detail::DistanceQuery query = detail::build_distance_query(soup, dopts);
    const std::vector<detail::DistanceHit> hits = detail::query_distances(query, centres, dopts);
    parallel_for_bw(static_cast<std::size_t>(ncells),
                    [&](std::size_t c) { occupied[c] = hits[c].mSignedDistance < 0.0 ? 1 : 0; });
    return occupied;
}

// Emit only the flagged cells, compacting the points they reference in ascending
// order so the output does not depend on traversal.
Mesh vox_build_subset(const detail::LatticeSpec& rSpec, const std::vector<char>& rOccupied,
                      std::int64_t Kept) {
    Mesh out;
    const std::int64_t nx = rSpec.mDims[0];
    const std::int64_t ny = rSpec.mDims[1];
    const std::int64_t px = nx + 1;
    const std::int64_t py = ny + 1;
    const std::int64_t npoints = detail::lattice_num_points(rSpec);
    const std::int64_t ncells = detail::lattice_num_cells(rSpec);

    // Two passes: mark which points the kept cells reference, then number them in
    // ASCENDING original order. That is surface.cpp's used/remap pattern, and the
    // ascending part is load-bearing rather than incidental -- numbering on first
    // encounter instead would make the point ids depend on the hexahedron's node
    // order, which is a traversal detail no caller should be able to observe (and
    // which the numpy twin would then have to replicate rather than simply sort).
    std::vector<char> used(static_cast<std::size_t>(npoints), 0);
    std::vector<std::int64_t> kept_cells;
    kept_cells.reserve(static_cast<std::size_t>(Kept));
    for (std::int64_t c = 0; c < ncells; ++c) {
        if (!rOccupied[static_cast<std::size_t>(c)])
            continue;
        kept_cells.push_back(c);
        const std::int64_t i = c % nx;
        const std::int64_t j = (c / nx) % ny;
        const std::int64_t k = c / (nx * ny);
        const std::int64_t base = (k * py + j) * px + i;
        const std::int64_t top = base + px * py;
        const std::int64_t nodes[8] = {base, base + 1, base + px + 1, base + px,
                                       top,  top + 1,  top + px + 1,  top + px};
        for (std::int64_t nd : nodes)
            used[static_cast<std::size_t>(nd)] = 1;
    }

    std::vector<std::int64_t> remap(static_cast<std::size_t>(npoints), -1);
    std::int64_t next = 0;
    for (std::int64_t p = 0; p < npoints; ++p)
        if (used[static_cast<std::size_t>(p)])
            remap[static_cast<std::size_t>(p)] = next++;

    std::vector<std::int64_t> conn;
    conn.reserve(static_cast<std::size_t>(Kept) * 8);
    for (std::int64_t c : kept_cells) {
        const std::int64_t i = c % nx;
        const std::int64_t j = (c / nx) % ny;
        const std::int64_t k = c / (nx * ny);
        const std::int64_t base = (k * py + j) * px + i;
        const std::int64_t top = base + px * py;
        const std::int64_t nodes[8] = {base, base + 1, base + px + 1, base + px,
                                       top,  top + 1,  top + px + 1,  top + px};
        for (std::int64_t nd : nodes)
            conn.push_back(remap[static_cast<std::size_t>(nd)]);
    }

    NDArray points =
        NDArray::Uninit(DType::Float64, {static_cast<std::size_t>(next), std::size_t{3}});
    double* pdst = points.As<double>();
    parallel_for_bw(static_cast<std::size_t>(npoints), [&](std::size_t p) {
        const std::int64_t slot = remap[p];
        if (slot < 0)
            return;
        const std::int64_t g = static_cast<std::int64_t>(p);
        const std::int64_t i = g % px;
        const std::int64_t j = (g / px) % py;
        const std::int64_t k = g / (px * py);
        pdst[slot * 3 + 0] = rSpec.mOrigin[0] + static_cast<double>(i) * rSpec.mSpacing[0];
        pdst[slot * 3 + 1] = rSpec.mOrigin[1] + static_cast<double>(j) * rSpec.mSpacing[1];
        pdst[slot * 3 + 2] = rSpec.mOrigin[2] + static_cast<double>(k) * rSpec.mSpacing[2];
    });
    out.AssignPoints(std::move(points));

    if (Kept > 0) {
        NDArray block =
            NDArray::Uninit(DType::Int64, {static_cast<std::size_t>(Kept), std::size_t{8}});
        std::memcpy(block.Data(), conn.data(), conn.size() * sizeof(std::int64_t));
        out.AddCellBlock("hexahedron", std::move(block));
    }
    return out;
}

}  // namespace

VoxelFill voxel_fill_from_name(const std::string& rName) {
    if (rName == "all")
        return VoxelFill::All;
    if (rName == "surface")
        return VoxelFill::Surface;
    if (rName == "inside")
        return VoxelFill::Inside;
    throw std::invalid_argument(std::string(kVoxPrefix) + "unknown fill '" + rName +
                                "' (expected one of: all, surface, inside)");
}

Mesh grid(const std::array<std::int64_t, 3>& rDims, const std::array<double, 3>& rOrigin,
          const std::array<double, 3>& rSpacing, std::int64_t MaxCells) {
    constexpr const char* prefix = "meshio++: grid: ";
    for (std::size_t k = 0; k < 3; ++k) {
        if (rDims[k] < 0)
            throw std::invalid_argument(std::string(prefix) +
                                        "cell counts must not be negative, got " +
                                        std::to_string(rDims[k]) + " on axis " + std::to_string(k));
        if (rDims[k] > 0 && !(rSpacing[k] > 0.0))
            throw std::invalid_argument(
                std::string(prefix) + "spacing must be positive on every axis with cells, got " +
                std::to_string(rSpacing[k]) + " on axis " + std::to_string(k));
    }
    detail::LatticeSpec spec;
    spec.mOrigin = rOrigin;
    spec.mSpacing = rSpacing;
    spec.mDims = rDims;
    vox_check_budget(detail::lattice_num_cells(spec), MaxCells, prefix);
    return detail::lattice_build_mesh(spec);
}

VoxelResult voxelize(const Mesh& rMesh, const VoxelOptions& rOptions) {
    const detail::LatticeSpec spec = vox_resolve_lattice(rMesh, rOptions);

    VoxelResult result;
    result.mDims = spec.mDims;
    result.mOrigin = spec.mOrigin;
    result.mSpacing = spec.mSpacing;

    // Every point and cell of the output is new, so nothing can be remapped --
    // the same situation slice/isosurface/extract_surface are in.
    detail::warn_regions_dropped(rMesh, "voxelize");

    const std::int64_t ncells = detail::lattice_num_cells(spec);
    const std::vector<char> occupied = vox_occupancy(rMesh, spec, rOptions);

    if (rOptions.mFill == VoxelFill::All || occupied.empty()) {
        result.mMesh = detail::lattice_build_mesh(spec);
        result.mNumOccupied = ncells;
        if (rOptions.mAttachOccupancy && ncells > 0) {
            // Every cell is kept, so occupancy is all ones -- constant, but
            // emitted anyway so that a caller can switch fill modes without
            // their downstream pipeline discovering the array has vanished.
            NDArray occ = NDArray::Uninit(DType::Int64, {static_cast<std::size_t>(ncells)});
            std::int64_t* dst = occ.As<std::int64_t>();
            parallel_for_bw(static_cast<std::size_t>(ncells), [&](std::size_t c) { dst[c] = 1; });
            std::vector<NDArray> blocks;
            blocks.push_back(std::move(occ));
            result.mMesh.AddCellData(kVoxelOccupancyName, std::move(blocks));
        }
        return result;
    }

    // A selective fill keeps a subset of the cells. Building the full lattice and
    // then subsetting it would cost the memory the budget check exists to avoid,
    // so the kept cells are emitted directly and the points they reference are
    // compacted in ascending order -- surface.cpp's used/remap pattern, which is
    // what makes the output independent of which thread found which cell.
    std::int64_t nkept = 0;
    for (std::int64_t c = 0; c < ncells; ++c)
        nkept += occupied[static_cast<std::size_t>(c)] ? 1 : 0;
    result.mNumOccupied = nkept;
    result.mMesh = vox_build_subset(spec, occupied, nkept);
    if (rOptions.mAttachOccupancy && nkept > 0) {
        NDArray occ = NDArray::Uninit(DType::Int64, {static_cast<std::size_t>(nkept)});
        std::int64_t* dst = occ.As<std::int64_t>();
        parallel_for_bw(static_cast<std::size_t>(nkept), [&](std::size_t c) { dst[c] = 1; });
        std::vector<NDArray> blocks;
        blocks.push_back(std::move(occ));
        result.mMesh.AddCellData(kVoxelOccupancyName, std::move(blocks));
    }
    return result;
}

}  // namespace meshioplusplus
