#ifdef MESHIOPLUSPLUS_HAS_ZLIB
             meshioplusplus::write_pvtp(p, mm, /*binary=*/true, /*zlib=*/true);
#else
             meshioplusplus::write_pvtp(p, mm, /*binary=*/true, /*zlib=*/false);
#endif
